const LAUNCH_ROSTER_RULE =
	"After the final launch, print a markdown table with the header row `| name | agent kind | role | model | worktree |`, the separator row `|---|---|---|---|---|`, and one row per child (worktree `none` when there is none), then use each name in prompts, handoffs, and results.";

export function buildSubagentRoutingGuidelines(
	catalog?: string,
	authenticatedTaskPreferences?: TaskPreferences,
	options: { launchRoster?: boolean } = {},
): string[] {
	return [
		"Act as the coordinator. Give each child one bounded outcome: goal, allowed files, verification, and whether to commit. Keep dependent writes sequential and parallelize only independent tasks.",
		"Children do not push, merge, deploy, or launch further agents unless their task allows it. Review each result or worktree yourself (diff against the reported base, run the relevant tests). Integration and cleanup are yours.",
		...(Object.keys(authenticatedTaskPreferences ?? {}).length > 0
			? [
					"For non-review work, prefer the configured task-category shortlists below. Omit thinking on task:<category> only when that category has configured thinking, clamped per candidate, or when you pass solutionSpace, from which an installed extension may set the child's level; explicit thinking overrides category thinking, then role and parent thinking are fallbacks when no category thinking is set. Use exact IDs for reviews when the authoring family is known.",
				]
			: [
					"For orchestrated subagent work, explicitly set both model and thinking for every child: first choose a fast, mid, or frontier provider-family tier matched to task complexity, then set thinking within that model's supported range.",
					"Use fast tier for bounded mechanical work and recon, mid tier for ordinary implementation or review, and frontier tier for architecture, security, hard diagnosis, or adversarial review. Use minimal/low thinking for mechanical work, medium for ordinary work, and high+ for hard work.",
				]),
		"Omitting model uses the role's model, then the configured models.agents entry and models.default, and only then the parent model. Omitting thinking uses task-category thinking, then the role's thinking, otherwise the parent level, which an installed extension may replace from solutionSpace.",
		"Without configured model or thinking defaults, omitted fields inherit the parent runtime; this is a discouraged fallback for orchestrated children.",
		"Before launching a new group of subagents, choose a short task slug and name each new child <task>-<role>[-n], for example login-api or login-test2. Use only plan, research, ui, api, build, test, review, browser, security, perf, or merge as roles; leave existing names unchanged. " +
			(options.launchRoster === false
				? "Use each name in prompts, handoffs, and results."
				: LAUNCH_ROSTER_RULE),
		catalog ??
			"Authenticated subagent model catalog becomes available after session start.",
	];
}

const ThinkingLevelSchema = Type.Union(
	THINKING_LEVELS.map((level) => Type.Literal(level)),
	{
		description:
			"Pi thinking level, within the chosen model's supported range. Overrides task-category thinking (clamped per candidate), then role thinking, then parent. Use low for mechanical work, medium for ordinary work, and high+ for hard work. Omitting uses task-category thinking, then the role's thinking, otherwise the parent level; an installed extension may set the child's level from solutionSpace instead.",
	},
);

export const SubagentParams = Type.Object({
	name: Type.String({
		description: "Short label shown in the widget and legacy pane title.",
	}),
	task: Type.String({ description: "Task/prompt for the sub-agent" }),
	agent: Type.Optional(
		Type.String({
			description:
				"Role definition to load defaults from (see subagents_list). Omit for a bare agent.",
		}),
	),
	systemPrompt: Type.Optional(
		Type.String({
			description:
				"Role/system-prompt text for a bare spawn. Named agents keep their definition body.",
		}),
	),
	model: Type.Optional(
		Type.String({
			description:
				"Exact authenticated provider/model-id, a comma-separated fallback list, or task:<category> as the whole value. Worktree launches take one model: a task: category uses its first candidate, and fallback lists are rejected. For ordinary review, prefer a different authenticated model family. When no other authenticated model family is available, ordinary review may use a same-family reviewer in a fresh standalone session. Disclose that this review is context-isolated, not cross-family independent. Cross-family verification must not use this fallback. Omitting uses the role's model, then the configured models.agents entry and models.default, then the parent model.",
		}),
	),
	thinking: Type.Optional(ThinkingLevelSchema),
	solutionSpace: Type.Optional(
		Type.String({
			description:
				"One or two sentences on how open-ended the work is, not the work itself: whether the fix or design is given, or which causes or designs remain open. The child receives it as PI_SUBAGENT_SOLUTION_SPACE, where an installed extension can choose the child's thinking level from it.",
		}),
	),
	skills: Type.Optional(
		Type.String({
			description: "Comma-separated skills (overrides agent default)",
		}),
	),
	tools: Type.Optional(
		Type.String({
			description: "Comma-separated tools (overrides agent default)",
		}),
	),
	cwd: Type.Optional(
		Type.String({
			description:
				"Working directory. With `worktree`, the source repository; the child then starts at the new worktree root.",
		}),
	),
	worktree: Type.Optional(
		Type.Union(
			[
				Type.Object({
					branch: Type.String({
						minLength: 1,
						description: "Unique new branch name.",
					}),
					base: Type.Optional(
						Type.String({
							description:
								"Git revision to branch from. Defaults to the committed HEAD.",
						}),
					),
				}),
				Type.Null(),
			],
			{
				description:
					"New managed Git worktree (legacy Herdr only, not Core). Omit or pass null for an ordinary child in cwd.",
			},
		),
	),
	fork: Type.Optional(
		Type.Boolean({
			description:
				"`true` copies this conversation into the child; `false` starts it fresh. Omit to use the role's session-mode.",
		}),
	),
	persistent: Type.Optional(
		Type.Boolean({
			description:
				"Keep the child alive between tasks. Send later tasks with subagent_send.",
		}),
	),
	notify: Type.Optional(
		Type.Boolean({
			description:
				"Persistent only. Give the specialist caller_notify, so it can wake you between tasks when something changes (at most 50 notices, rate-limited). Default false.",
		}),
	),
	accept: Type.Optional(
		Type.Object(
			{
				run: Type.String({
					minLength: 1,
					description:
						"Shell command run with `sh -c`; exit 0 passes. The child runs it and retries on failure. The host then reruns it in the child's checkout, and that run decides the verdict.",
				}),
				maxRetries: Type.Optional(
					Type.Integer({
						minimum: 0,
						maximum: ACCEPT_MAX_RETRIES,
						description: "Extra child turns after a failed check. Default 1.",
					}),
				),
				timeoutSec: Type.Optional(
					Type.Integer({
						minimum: 1,
						maximum: ACCEPT_MAX_TIMEOUT_SEC,
						description:
							"Per-run timeout in seconds. Default 600. A timeout gives verdict `error`.",
					}),
				),
				paths: Type.Optional(
					Type.Array(Type.String({ minLength: 1 }), {
						description:
							"Check files, such as tests. The result lists any the child changed, without affecting the verdict.",
					}),
				),
			},
			{
				description:
					"Optional acceptance check. The result reports `Check: <verdict>`: accepted, rejected, error, skipped, or none. Only for auto-exit, non-persistent children.",
			},
		),
	),
	interactive: Type.Optional(
		Type.Boolean({
			description:
				"True when the user drives the child in its own pane. Interactive children do not wake the parent on stall or recovery. Defaults to the role's `interactive` setting, else the opposite of `auto-exit`.",
		}),
	),
});

/** Tools that are gated by `spawning: false` */
const SPAWNING_TOOLS = new Set([
	"subagent",
	"subagent_interrupt",
	"subagent_cancel",
	"subagents_list",
	"subagent_resume",
	"subagent_send",
	"subagent_stop",
	"subagents_write_task_models",
]);

/**
 * Resolve the effective set of denied tool names from agent defaults.
 * `spawning: false` expands to all SPAWNING_TOOLS.
 * `deny-tools` adds individual tool names on top.
 */
export function resolveDenyTools(agentDefs: AgentDefaults | null): Set<string> {
	const denied = new Set<string>();
	if (!agentDefs) return denied;

	// spawning: false → deny all spawning tools
	if (agentDefs.spawning === false) {
		for (const t of SPAWNING_TOOLS) denied.add(t);
	}

	// deny-tools: explicit list
	if (agentDefs.denyTools) {
		for (const t of agentDefs.denyTools
			.split(",")
			.map((s) => s.trim())
			.filter(Boolean)) {
			denied.add(t);
		}
	}

	return denied;
}

export function discoverAgentCatalog(
	pi?: Pick<ExtensionAPI, "events">,
): AgentCatalog {
	return discoverCoreAgentCatalog({
		agentConfigDir: getAgentConfigDir(),
		cwd: process.cwd(),
		onRolePackDiscovered: pi?.events
			? (event) => pi.events.emit(ROLE_PACK_DISCOVERY_EVENT, event)
			: undefined,
	});
}

export function missingRoleMessage(agentName: string): string {
	return `Agent "${agentName}" was not found. pi-herdr-agents ships no roles: define it in .pi/agents or the global agents directory, install a role pack that provides it, or omit agent for a bare launch.`;
}

function formatAgentSource(agent: ListedAgentDefinition): string {
	return agent.source === "package" && agent.provider
		? `package:${agent.provider}`
		: agent.source;
}

export function formatVisibleAgentDefinitions(
	agents: ListedAgentDefinition[],
): string[] {
	return agents
		.filter((agent) => !agent.disableModelInvocation)
		.map((agent) => {
			// Definitions are files a child may be able to write: encode each value.
			const badge = ` (${encodeHostValue(formatAgentSource(agent))})`;
			const desc = agent.description
				? ` — ${encodeHostValue(agent.description, HOST_PATH_CHARS)}`
				: "";
			const model = agent.model ? ` [${encodeHostValue(agent.model)}]` : "";
			return `• ${encodeHostValue(agent.name)}${badge}${model}${desc}`;
		});
}

export function formatAgentDiagnostics(
	diagnostics: AgentDiagnostic[],
): string[] {
	return diagnostics.map(
		(diagnostic) =>
			`! ${encodeHostValue(diagnostic.message, HOST_ERROR_CHARS)}`,
	);
}

export function resolveEffectiveSessionMode(
	params: Static<typeof SubagentParams>,
	agentDefs: AgentDefaults | null,
): SubagentSessionMode {
	if (params.fork === true) return "fork";
	if (params.fork === false) return "standalone";
	return agentDefs?.sessionMode ?? "standalone";
}

interface LaunchBehavior {
	sessionMode: SubagentSessionMode;
	seededSessionMode: "lineage-only" | "fork" | null;
	inheritsConversationContext: boolean;
	taskDelivery: "direct" | "artifact";
}

export function resolveLaunchBehavior(
	params: Static<typeof SubagentParams>,
	agentDefs: AgentDefaults | null,
): LaunchBehavior {
	const sessionMode = resolveEffectiveSessionMode(params, agentDefs);
	const inheritsConversationContext = sessionMode === "fork";
	return {
		sessionMode,
		seededSessionMode: sessionMode === "standalone" ? null : sessionMode,
		inheritsConversationContext,
		taskDelivery: inheritsConversationContext ? "direct" : "artifact",
	};
}

/**
 * Decide whether a subagent is interactive (user-driven, long-running).
 *
 * Resolution order:
 *   1. Explicit `interactive` tool parameter wins.
 *   2. Explicit `interactive` frontmatter field on the agent.
 *   3. Default: the inverse of `auto-exit`. Agents that auto-exit are
 *      autonomous and the parent session should be woken on stall/recovery
 *      transitions. Agents that don't auto-exit are driven by the user in
 *      their own pane, and stall pings are noise.
 *
 * Bare `subagent({ name, task })` calls have no agent defs; they auto-exit
 * unless the caller passes `interactive: true`.
 */
export function resolveEffectivePersistent(
	params: Static<typeof SubagentParams>,
	agentDefs: AgentDefaults | null,
): boolean {
	return params.persistent ?? agentDefs?.persistent ?? false;
}

export function resolveEffectiveAutoExit(
	params: Static<typeof SubagentParams>,
	agentDefs: AgentDefaults | null,
): boolean {
	if (resolveEffectivePersistent(params, agentDefs)) return false;
	// Named agents preserve their declared behavior. Bare tool calls are
	// autonomous by default, including full-context forks: `fork` controls
	// context inheritance, not whether the child should remain open. Interactive
	// bare launches opt out explicitly with `interactive: true`.
	if (agentDefs) return agentDefs.autoExit ?? false;
	return params.interactive !== true;
}

export function resolveEffectiveInteractive(
	params: Static<typeof SubagentParams>,
	agentDefs: AgentDefaults | null,
): boolean {
	if (params.interactive != null) return params.interactive;
	if (resolveEffectivePersistent(params, agentDefs)) return false;
	if (agentDefs?.interactive != null) return agentDefs.interactive;
	return !resolveEffectiveAutoExit(params, agentDefs);
}

export function loadAgentDefaults(
	agentName: string,
	pi?: Pick<ExtensionAPI, "events">,
): ListedAgentDefinition | null {
	return (
		discoverAgentCatalog(pi).agents.find((agent) => agent.name === agentName) ??
		null
	);
}
